const now = DateTime.now().setZone('Europe/Paris');
const debut = now.minus({ days: 7 }).startOf('day');
const sens = /(prix|tarif|co[uû]t|marge|chiffre d.?affaires|\bca\b|salaire|paie|b[ée]n[ée]fice|facture|montant|€|euro|mot de passe|password|identifiant|banque|\brib\b|iban)/i;
const refus = /(pas acc[eè]s|n.?ai pas acc[eè]s|je ne peux pas|pas autoris|non autoris|confidenti)/i;
const rows = $('Lire journal').all().map(i => i.json);
const parNom = {};
for (const r of rows) {
  if (String(r.workflow || '') === 'brief') continue;
  const d = DateTime.fromFormat(String(r.horodatage || ''), 'yyyy-MM-dd HH:mm:ss', { zone: 'Europe/Paris' });
  if (!d.isValid || d < debut) continue;
  const nom = String(r.utilisateur || '?').replace(/\s*\(.*\)$/, '');
  const s = parNom[nom] = parNom[nom] || { n: 0, hors: 0, quota: 0 };
  s.n++;
  const q = String(r.question || ''), rep = String(r.reponse || '');
  if (/limite de 30 questions/.test(rep)) s.quota++;
  else if (sens.test(q) || refus.test(rep)) s.hors++;
}
const noms = Object.keys(parNom).sort((a, b) => parNom[b].n - parNom[a].n);
const L = ['Bilan bot, 7 derniers jours :'];
if (!noms.length) L.push('Aucune question.');
for (const n of noms) {
  const s = parNom[n];
  L.push('- ' + n + ' : ' + s.n + ' question' + (s.n > 1 ? 's' : '') + (s.hors ? ', ' + s.hors + ' hors sujet ou sensible' : '') + (s.quota ? ', quota atteint ' + s.quota + ' fois' : ''));
}
const total = noms.reduce((a, n) => a + parNom[n].hors, 0);
if (total) L.push('Detail dans le journal Google Sheet.');
const admins = $('Lire destinataires').all().map(i => i.json).filter(u => u.actif && u.role === 'admin' && u.telegram_id);
return admins.map(a => ({ json: { chat_id: String(a.telegram_id), text: L.join('\n') } }));
